SELECT category_id, name, description
  FROM m_category
 WHERE category_id = #{categoryId}

SELECT product_id, category_id, name, description
  FROM m_product
 WHERE category_id = #{categoryId}
 ORDER BY product_id
 LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
  FROM m_product
 WHERE category_id = #{categoryId}

SELECT product_id, category_id, name, description
  FROM m_product
 WHERE product_id = #{productId}

SELECT COUNT(*)
  FROM m_item
 WHERE product_id = #{productId}
